--- global settings.json (search hooks + catalyst) ---
{
  "Notification": [
    {
      "hooks": [
        {
          "type": "command",
          "command": "[ -f \"$HOME/.petdex/runtime/hooks-disabled\" ] && exit 0; [ -x \"$HOME/.petdex/bin/petdex-hook\" ] && exec \"$HOME/.petdex/bin/petdex-hook\" bubble notification claude-code; exit 0"
        }
      ]
    }
  ],
  "PermissionRequest": [
    {
      "matcher": "*",
      "hooks": [
        {
          "type": "command",
          "command": "\"${CLAUDE_CONFIG_DIR:-$HOME/.claude}/hooks/notchi-hook.sh\""
        }
      ]
    }
  ],
  "PostCompact": [
    {
      "hooks": [
        {
          "type": "command",
          "command": "'$HOME/.caveman/bin/caveman-proxy' native-hook claude --adapter '$HOME/.local/share/fnm/aliases/default/lib/node_modules/@caveman-ai/cli/dist/native-hook-fast.js'"
        }
      ]
    }
  ],
  "PostToolUse": [
    {
      "matcher": "*",
      "hooks": [
        {
          "type": "command",
          "command": "\"${CLAUDE_CONFIG_DIR:-$HOME/.claude}/hooks/notchi-hook.sh\""
        }
      ]
    },
    {
      "hooks": [
        {
          "type": "command",
          "command": "[ -f \"$HOME/.petdex/runtime/hooks-disabled\" ] && exit 0; [ -x \"$HOME/.petdex/bin/petdex-hook\" ] && exec \"$HOME/.petdex/bin/petdex-hook\" bubble post claude-code; exit 0"
        }
      ]
    },
    {
      "hooks": [
        {
          "type": "command",
          "command": "'$HOME/.caveman/bin/caveman-proxy' native-hook claude --adapter '$HOME/.local/share/fnm/aliases/default/lib/node_modules/@caveman-ai/cli/dist/native-hook-fast.js'"
        }
      ]
    }
  ],
  "PostToolUseFailure": [
    {
      "hooks": [
        {
          "type": "command",
          "command": "'$HOME/.caveman/bin/caveman-proxy' native-hook claude --adapter '$HOME/.local/share/fnm/aliases/default/lib/node_modules/@caveman-ai/cli/dist/native-hook-fast.js'"
        }
      ]
    }
  ],
  "PreCompact": [
    {
      "matcher": "auto",
      "hooks": [
        {
          "type": "command",
          "command": "\"${CLAUDE_CONFIG_DIR:-$HOME/.claude}/hooks/notchi-hook.sh\""
        }
      ]
    },
    {
      "matcher": "manual",
      "hooks": [
        {
          "type": "command",
          "command": "\"${CLAUDE_CONFIG_DIR:-$HOME/.claude}/hooks/notchi-hook.sh\""
        }
      ]
    },
    {
      "hooks": [
        {
          "type": "command",
          "command": "'$HOME/.caveman/bin/caveman-proxy' native-hook claude --adapter '$HOME/.local/share/fnm/aliases/default/lib/node_modules/@caveman-ai/cli/dist/native-hook-fast.js'"
        }
      ]
    }
  ],
  "PreToolUse": [
    {
      "matcher": "Bash",
      "hooks": [
        {
          "type": "command",
          "command": "rtk hook claude"
        }
      ]
    },
    {
      "matcher": "Skill",
      "hooks": [
        {
          "type": "command",
          "command": "bunx -y ccstatusline@latest --hook"
        }
      ]
    },
    {
      "matcher": "*",
      "hooks": [
        {
          "type": "command",
          "command": "\"${CLAUDE_CONFIG_DIR:-$HOME/.claude}/hooks/notchi-hook.sh\""
        }
      ]
    },
    {
      "hooks": [
        {
          "type": "command",
          "command": "[ -f \"$HOME/.petdex/runtime/hooks-disabled\" ] && exit 0; [ -x \"$HOME/.petdex/bin/petdex-hook\" ] && exec \"$HOME/.petdex/bin/petdex-hook\" bubble pre claude-code; exit 0"
        }
      ]
    },
    {
      "hooks": [
        {
          "type": "command",
          "command": "'$HOME/.caveman/bin/caveman-proxy' native-hook claude --adapter '$HOME/.local/share/fnm/aliases/default/lib/node_modules/@caveman-ai/cli/dist/native-hook-fast.js'"
        }
      ]
    },
    {
      "hooks": [
        {
          "type": "command",
          "command": "'$HOME/.local/share/fnm/aliases/default/bin/caveman' shrink-hook"
        }
      ]
    }
  ],

